.5 rounded-full border bg-muted px-3 py-1 text-xs font-medium text-muted-foreground"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-brain size-3"><path d="M12 5a3 3 0 1 0-5.997.125 4 4 0 0 0-2.526 5.77 4 4 0 0 0 .556 6.588A4 4 0 1 0 12 18Z"></path><path d="M12 5a3 3 0 1 1 5.997.125 4 4 0 0 1 2.526 5.77 4 4 0 0 1-.556 6.588A4 4 0 1 1 12 18Z"></path><path d="M15 13a4.5 4.5 0 0 1-3-4 4.5 4.5 0 0 1-3 4"></path><path d="M17.599 6.5a3 3 0 0 0 .399-1.375"></path><path d="M6.003 5.125A3 3 0 0 0 6.401 6.5"></path><path d="M3.477 10.896a4 4 0 0 1 .585-.396"></path><path d="M19.938 10.5a4 4 0 0 1 .585.396"></path><path d="M6 18a4 4 0 0 1-1.967-.516"></path><path d="M19.967 17.484A4 4 0 0 1 18 18"></path></svg>Flashcard SRS</div></div><h2 class="mb-3 text-center text-2xl font-bold tracking-tight">Intelligens ismétlési rendszer — mint az Anki</h2><p class="mb-12 mx-auto max-w-2xl text-center text-muted-foreground">Az SRS algoritmus pontosan kiszámolja, mikor kell ismételned — így nem pazarolsz időt arra, amit már tudsz.</p><div class="mb-12 mx-auto max-w-sm"><div class="overflow-hidden rounded-2xl border bg-card shadow-lg"><div class="border-b px-6 pb-4 pt-6 text-center"><p class="mb-1 text-xs text-muted-foreground">Deck: Angol alapszavak · 12/40</p><p class="mb-2 mt-4 text-3xl font-bold tracking-tight">between</p><p class="text-sm text-muted-foreground">/bɪˈtwiːn/</p><div class="mt-4 border-t pt-4"><p class="text-lg font-medium">között, -ek között</p><p class="mt-1 text-xs italic text-muted-foreground">&quot;between you and me&quot;</p></div></div><div class="grid grid-cols-4 divide-x"><div class="cursor-pointer py-3 text-center transition-colors hover:bg-muted/50 text-red-600 dark:text-red-400"><div class="text-xs font-semibold">Újra</div><div class="mt-0.5 text-[10px] text-muted-foreground">1 perc</div></div><div class="cursor-pointer py-3 text-center transition-colors hover:bg-muted/50 text-orange-600 dark:text-orange-400"><div class="text-xs font-semibold">Nehéz</div><div class="mt-0.5 text-[10px] text-muted-foreground">6 nap</div></div><div class="cursor-pointer py-3 text-center transition-colors hover:bg-muted/50 text-blue-600 dark:text-blue-400"><div class="text-xs font-semibold">Jó</div><div class="mt-0.5 text-[10px] text-muted-foreground">10 nap</div></div><div class="cursor-pointer py-3 text-center transition-colors hover:bg-muted/50 text-green-600 dark:text-green-400"><div class="text-xs font-semibold">Könnyű</div><div class="mt-0.5 text-[10px] text-muted-foreground">15 nap</div></div></div></div></div><div class="grid gap-6 sm:grid-cols-2 lg:grid-cols-3"><div class="flex gap-4 rounded-xl border bg-card p-5"><div class="mt-0.5 flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-violet-100 dark:bg-violet-950/40"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-layers size-4 text-violet-600 dark:text-violet-400"><path d="M12.83 2.18a2 2 0 0 0-1.66 0L2.6 6.08a1 1 0 0 0 0 1.83l8.58 3.91a2 2 0 0 0 1.66 0l8.58-3.9a1 1 0 0 0 0-1.83z"></path><path d="M2 12a1 1 0 0 0 .58.91l8.6 3.91a2 2 0 0 0 1.65 0l8.58-3.9A1 1 0 0 0 22 12"></path><path d="M2 17a1 1 0 0 0 .58.91l8.6 3.91a2 2 0 0 0 1.65 0l8.58-3.9A1 1 0 0 0 22 17"></path></svg></div><div><h3 class="mb-1 text-sm font-semibold">Saját deck-ek</h3><p class="text-xs leading-relaxed text-muted-foreground">Tetszőleges számú kártyacsomagot hozhatsz létre különböző témákhoz. Mappákkal is szervezheted.</p></div></div><div class="flex gap-4 rounded-xl border bg-card p-5"><div class="mt-0.5 flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-violet-100 dark:bg-violet-950/40"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-repeat2 size-4 text-violet-600 dark:text-violet-400"><path d="m2 9 3-3 3 3"></path><path d="M13 18H7a2 2 0 0 1-2-2V6"></path><path d="m22 15-3 3-3-3"></path><path d="M11 6h6a2 2 0 0 1 2 2v10"></path></svg></div><div><h3 class="mb-1 text-sm font-semibold">Kétirányú kártyák</h3><p class="text-xs leading-relaxed text-muted-foreground">Előlap→hátlap, hátlap→előlap, vagy mindkét irány — külön-külön értékeli az algoritmus.</p></div></div><div class="flex gap-4 rounded-xl border bg-card p-5"><div class="mt-0.5 flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-violet-100 dark:bg-violet-950/40"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-volume2 size-4 text-violet-600 dark:text-violet-400"><path d="M11 4.702a.705.705 0 0 0-1.203-.498L6.413 7.587A1.4 1.4 0 0 1 5.416 8H3a1 1 0 0 0-1 1v6a1 1 0 0 0 1 1h2.416a1.4 1.4 0 0 1 .997.413l3.383 3.384A.705.705 0 0 0 11 19.298z"></path><path d="M16 9a5 5 0 0 1 0 6"></path><path d="M19.364 18.364a9 9 0 0 0 0-12.728"></path></svg></div><div><h3 class="mb-1 text-sm font-semibold">Hangos felolvasás</h3><p class="text-xs leading-relaxed text-muted-foreground">Az előlap és hátlap szövege felolvasható — tanuld a helyes kiejtést is egyszerre.</p></div></div><div class="flex gap-4 rounded-xl border bg-card p-5"><div class="mt-0.5 flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-violet-100 dark:bg-violet-950/40"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-shuffle size-4 text-violet-600 dark:text-violet-400"><path d="m18 14 4 4-4 4"></path><path d="m18 2 4 4-4 4"></path><path d="M2 18h1.973a4 4 0 0 0 3.3-1.7l5.454-8.6a4 4 0 0 1 3.3-1.7H22"></path><path d="M2 6h1.972a4 4 0 0 1 3.6 2.2"></path><path d="M22 18h-6.041a4 4 0 0 1-3.3-1.8l-.359-.45"></path></svg></div><div><h3 class="mb-1 text-sm font-semibold">Kártyák keverése</h3><p class="text-xs leading-relaxed text-muted-foreground">Bekapcsolható keverés — így kétoldalú kártyáknál az előlap és hátlap nem kerül egymás mellé.</p></div></div><div class="flex gap-4 rounded-xl border bg-card p-5"><div class="mt-0.5 flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-violet-100 dark:bg-violet-950/40"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-upload size-4 text-violet-600 dark:text-violet-400"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"></path><polyline points="17 8 12 3 7 8"></polyline><line x1="12" x2="12" y1="3" y2="15"></line></svg></div><div><h3 class="mb-1 text-sm font-semibold">Import a szólistáról</h3><p class="text-xs leading-relaxed text-muted-foreground">A TopWords szólistájából egy kattintással importálhatsz kártyát a meglévő definíciókkal.</p></div></div><div class="flex gap-4 rounded-xl border bg-card p-5"><div class="mt-0.5 flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-violet-100 dark:bg-violet-950/40"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-download size-4 text-violet-600 dark:text-violet-400"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"></path><polyline points="7 10 12 15 17 10"></polyline><line x1="12" x2="12" y1="15" y2="3"></line></svg></div><div><h3 class="mb-1 text-sm font-semibold">CSV import / export</h3><p class="text-xs leading-relaxed text-muted-foreground">Importálj kártyákat CSV fájlból, vagy exportáld a deckjed — kompatibilis más alkalmazásokkal.</p></div></div><div class="flex gap-4 rounded-xl border bg-card p-5"><div class="mt-0.5 flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-violet-100 dark:bg-violet-950/40"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-settings2 size-4 text-violet-600 dark:text-violet-400"><path d="M20 7h-9"></path><path d="M14 17H5"></path><circle cx="17" cy="17" r="3"></circle><circle cx="7" cy="7" r="3"></circle></svg></div><div><h3 class="mb-1 text-sm font-semibold">Deckenként testreszabható</h3><p class="text-xs leading-relaxed text-muted-foreground">Minden decknek saját beállítása: napi korlát, tanulási lépések, ease faktorok, keverés.</p></div></div><div class="flex gap-4 rounded-xl border bg-card p-5"><div class="mt-0.5 flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-violet-100 dark:bg-violet-950/40"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-trending-up size-4 text-violet-600 dark:text-violet-400"><polyline points="22 7 13.5 15.5 8.5 10.5 2 17"></polyline><polyline points="16 7 22 7 22 13"></polyline></svg></div><div><h3 class="mb-1 text-sm font-semibold">Haladás nyomon követése</h3><p class="text-xs leading-relaxed text-muted-foreground">Minden kártya státusza látható: Új · Tanulás · Ismétlés · Újratanulás — és mikor esedékes.</p></div></div><div class="flex gap-4 rounded-xl border bg-card p-5"><div class="mt-0.5 flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-violet-100 dark:bg-violet-950/40"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-refresh-cw size-4 text-violet-600 dark:text-violet-400"><path d="M3 12a9 9 0 0 1 9-9 9.75 9.75 0 0 1 6.74 2.74L21 8"></path><path d="M21 3v5h-5"></path><path d="M21 12a9 9 0 0 1-9 9 9.75 9.75 0 0 1-6.74-2.74L3 16"></path><path d="M8 16H3v5"></path></svg></div><div><h3 class="mb-1 text-sm font-semibold">Leech detektálás</h3><p class="text-xs leading-relaxed text-muted-foreground">A sokat tévesztett kártyákat automatikusan jelöli, hogy tudd, hol érdemes más módszert alkalmazni.</p></div></div></div><div class="mt-12 rounded-2xl border bg-muted/40 p-8"><h3 class="mb-2 text-center font-semibold">Hogyan működik az SRS algoritmus?</h3><p class="mx-auto mb-8 max-w-2xl text-center text-sm text-muted-foreground">Minden értékelés után kiszámolja, mikor kellene visszamutatnia a kártyát — ha könnyen ment, tovább vár; ha nehéz volt, hamarabb visszahozza.</p><div class="grid gap-4 text-center sm:grid-cols-4"><div class="rounded-xl border p-4 border-red-200 dark:border-red-900 bg-red-50 dark:bg-red-950/30"><div class="mb-1 text-base font-bold text-red-700 dark:text-red-400">Újra</div><p class="text-xs text-muted-foreground">Visszakerül a tanulási lépések elejére</p></div><div class="rounded-xl border p-4 border-orange-200 dark:border-orange-900 bg-orange-50 dark:bg-orange-950/30"><div class="mb-1 text-base font-bold text-orange-700 dark:text-orange-400">Nehéz</div><p class="text-xs text-muted-foreground">Kisebb intervallum, csökkenő ease</p></div><div class="rounded-xl border p-4 border-blue-200 dark:border-blue-900 bg-blue-50 dark:bg-blue-950/30"><div class="mb-1 text-base font-bold text-blue-700 dark:text-blue-400">Jó</div><p class="text-xs text-muted-foreground">Intervallum nő az ease faktor alapján</p></div><div class="rounded-xl border p-4 border-green-200 dark:border-green-900 bg-green-50 dark:bg-green-950/30"><div class="mb-1 text-base font-bold text-green-700 dark:text-green-400">Könnyű</div><p class="text-xs text-muted-foreground">Tovább vár, ease faktor nő</p></div></div></div></div></section><section class="border-t"><div class="mx-auto max-w-5xl px-6 py-20"><div class="grid items-center gap-12 md:grid-cols-2"><div class="flex flex-col gap-3"><div class="rounded-xl border bg-card p-6 text-center shadow-sm"><p class="mb-1 text-xs text-muted-foreground">#42 · Kezdő szint</p><p class="text-3xl font-bold tracking-tight">between</p><p class="mt-2 text-sm text-muted-foreground">Mi a magyar jelentése?</p></div><div class="grid grid-cols-2 gap-2"><div class="rounded-lg border px-4 py-2.5 text-center text-sm font-medium border-green-500 bg-green-50 text-green-800 dark:bg-green-950/30 dark:text-green-300">között</div><div class="rounded-lg border px-4 py-2.5 text-center text-sm font-medium bg-background text-muted-foreground opacity-50">felett</div><div class="rounded-lg border px-4 py-2.5 text-center text-sm font-medium bg-background text-muted-foreground opacity-50">mellett</div><div class="rounded-lg border px-4 py-2.5 text-center text-sm font-medium bg-background text-muted-foreground opacity-50">mögött</div></div></div><div><div class="mb-3 inline-flex items-center gap-1.5 rounded-full border bg-muted px-3 py-1 text-xs font-medium text-muted-foreground"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-swords size-3"><polyline points="14.5 17.5 3 6 3 3 6 3 17.5 14.5"></polyline><line x1="13" x2="19" y1="19" y2="13"></line><line x1="16" x2="20" y1="16" y2="20"></line><line x1="19" x2="21" y1="21" y2="19"></line><polyline points="14.5 6.5 18 3 21 3 21 6 17.5 9.5"></polyline><line x1="5" x2="9" y1="14" y2="18"></line><line x1="7" x2="4" y1="17" y2="20"></line><line x1="3" x2="5" y1="19" y2="21"></line></svg>Kvíz mód</div><h2 class="mb-4 text-2xl font-bold tracking-tight">Teszteld magad kvíz módban</h2><p class="mb-6 text-muted-foreground">Válaszd ki melyik szavakból és hányból kvízzeljünk — a rendszer automatikusan generálja a kérdéseket és a válaszlehetőségeket.</p><ul class="flex flex-col gap-3 text-sm"><li class="flex items-start gap-3"><div class="mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-primary/10"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-check-check size-3 text-primary"><path d="M18 6 7 17l-5-5"></path><path d="m22 10-7.5 7.5L13 16"></path></svg></div><span class="text-muted-foreground">Szűrj státusz szerint – tanulom, elmentettem, tudom</span></li><li class="flex items-start gap-3"><div class="mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-primary/10"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-trending-up size-3 text-primary"><polyline points="22 7 13.5 15.5 8.5 10.5 2 17"></polyline><polyline points="16 7 22 7 22 13"></polyline></svg></div><span class="text-muted-foreground">Válassz nehézségi szintet – kezdőtől haladóig</span></li><li class="flex items-start gap-3"><div class="mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-primary/10"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-zap size-3 text-primary"><path d="M4 14a1 1 0 0 1-.78-1.63l9.9-10.2a.5.5 0 0 1 .86.46l-1.92 6.02A1 1 0 0 0 13 10h7a1 1 0 0 1 .78 1.63l-9.9 10.2a.5.5 0 0 1-.86-.46l1.92-6.02A1 1 0 0 0 11 14z"></path></svg></div><span class="text-muted-foreground">10, 20, 50 kérdés – vagy az összes elérhető szó egyszerre</span></li><li class="flex items-start gap-3"><div class="mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-primary/10"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-folder-open size-3 text-primary"><path d="m6 14 1.5-2.9A2 2 0 0 1 9.24 10H20a2 2 0 0 1 1.94 2.5l-1.54 6a2 2 0 0 1-1.95 1.5H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h3.9a2 2 0 0 1 1.69.9l.81 1.2a2 2 0 0 0 1.67.9H18a2 2 0 0 1 2 2v2"></path></svg></div><span class="text-muted-foreground">Mappa szerint – csak egy adott témából kvízzelhetsz</span></li></ul></div></div></div></section><section class="border-t bg-muted/40"><div class="mx-auto max-w-5xl px-6 py-20"><div class="grid items-center gap-12 md:grid-cols-2"><div><div class="mb-3 inline-flex items-center gap-1.5 rounded-full border bg-muted px-3 py-1 text-xs font-medium text-muted-foreground"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-scan-text size-3"><path d="M3 7V5a2 2 0 0 1 2-2h2"></path><path d="M17 3h2a2 2 0 0 1 2 2v2"></path><path d="M21 17v2a2 2 0 0 1-2 2h-2"></path><path d="M7 21H5a2 2 0 0 1-2-2v-2"></path><path d="M7 8h8"></path><path d="M7 12h10"></path><path d="M7 16h6"></path></svg>Szövegelemzés</div><h2 class="mb-4 text-2xl font-bold tracking-tight">Elemezz bármilyen angol szöveget</h2><p class="mb-6 text-muted-foreground">Illeszd be a szöveget, adj meg egy webcímet — vagy egy YouTube videót — és az alkalmazás azonnal megmutatja, mennyit értesz belőle.</p><ul class="flex flex-col gap-3 text-sm"><li class="flex items-start gap-3"><div class="mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-primary/10"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-check-check size-3 text-primary"><path d="M18 6 7 17l-5-5"></path><path d="m22 10-7.5 7.5L13 16"></path></svg></div><span class="text-muted-foreground">Érthetőség % — látod, hány szót ismersz a szövegben</span></li><li class="flex items-start gap-3"><div class="mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-primary/10"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-scan-text size-3 text-primary"><path d="M3 7V5a2 2 0 0 1 2-2h2"></path><path d="M17 3h2a2 2 0 0 1 2 2v2"></path><path d="M21 17v2a2 2 0 0 1-2 2h-2"></path><path d="M7 21H5a2 2 0 0 1-2-2v-2"></path><path d="M7 8h8"></path><path d="M7 12h10"></path><path d="M7 16h6"></path></svg></div><span class="text-muted-foreground">Kiemelés — zölddel, kékkel, pirossal jelöli a szavakat státusz szerint</span></li><li class="flex items-start gap-3"><div class="mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-primary/10"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-youtube size-3 text-red-500"><path d="M2.5 17a24.12 24.12 0 0 1 0-10 2 2 0 0 1 1.4-1.4 49.56 49.56 0 0 1 16.2 0A2 2 0 0 1 21.5 7a24.12 24.12 0 0 1 0 10 2 2 0 0 1-1.4 1.4 49.55 49.55 0 0 1-16.2 0A2 2 0 0 1 2.5 17"></path><path d="m10 15 5-3-5-3z"></path></svg></div><span class="text-muted-foreground">YouTube felirat — bármely videó angol felirata elemezhető</span></li><li class="flex items-start gap-3"><div class="mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-primary/10"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-pencil-line size-3 text-violet-500"><path d="M12 20h9"></path><path d="M16.376 3.622a1 1 0 0 1 3.002 3.002L7.368 18.635a2 2 0 0 1-.855.506l-2.872.838a.5.5 0 0 1-.62-.62l.838-2.872a2 2 0 0 1 .506-.854z"></path><path d="m15 5 3 3"></path></svg></div><span class="text-muted-foreground">Szóra kattintva — megjelenítés, státusz változtatás, saját szóként mentés</span></li><li class="flex items-start gap-3"><div class="mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-primary/10"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-clock size-3 text-blue-500"><circle cx="12" cy="12" r="10"></circle><polyline points="12 6 12 12 16 14"></polyline></svg></div><span class="text-muted-foreground">Előzmények — az utolsó 10 elemzés automatikusan mentve</span></li></ul></div><div class="overflow-hidden rounded-xl border bg-card shadow-sm"><div class="flex items-center justify-between border-b bg-muted/40 px-4 py-3"><span class="text-sm font-medium">Szövegelemzés</span><span class="text-2xl font-bold text-green-600">87%</span></div><div class="border-b px-4 py-3"><div class="mb-1 h-2 w-full overflow-hidden rounded-full bg-secondary"><div class="h-2 rounded-full bg-green-500" style="width:87%"></div></div><p class="text-xs text-muted-foreground">312 ismert szó / 358 szó összesen</p></div><div class="px-4 py-4 text-sm leading-7"><p class="text-sm"><span class="rounded bg-green-100 px-0.5 text-green-900 dark:bg-green-900/40 dark:text-green-300">The</span> <span class="rounded bg-green-100 px-0.5 text-green-900 dark:bg-green-900/40 dark:text-green-300">quick</span> <span class="rounded bg-blue-100 px-0.5 text-blue-900 dark:bg-blue-900/40 dark:text-blue-300">brown</span> <span class="rounded bg-red-100 px-0.5 text-red-900 dark:bg-red-900/40 dark:text-red-300">fox</span> <span class="rounded bg-green-100 px-0.5 text-green-900 dark:bg-green-900/40 dark:text-green-300">jumps</span> over the <span class="rounded bg-green-100 px-0.5 text-green-900 dark:bg-green-900/40 dark:text-green-300">lazy</span> dog.</p></div><div class="flex flex-wrap gap-3 border-t px-4 py-3 text-xs text-muted-foreground"><span class="flex items-center gap-1"><span class="inline-block size-2.5 rounded-sm bg-green-400"></span> Tudom</span><span class="flex items-center gap-1"><span class="inline-block size-2.5 rounded-sm bg-blue-400"></span> Tanulom</span><span class="flex items-center gap-1"><span class="inline-block size-2.5 rounded-sm bg-red-400"></span> Top 10k, ismeretlen</span></div></div></div></div></section><section class="border-t"><div class="mx-auto max-w-5xl px-6 py-20"><div class="grid gap-12 md:grid-cols-2"><div><div class="mb-3 inline-flex items-center gap-1.5 rounded-full border bg-muted px-3 py-1 text-xs font-medium text-muted-foreground"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-pencil-line size-3"><path d="M12 20h9"></path><path d="M16.376 3.622a1 1 0 0 1 3.002 3.002L7.368 18.635a2 2 0 0 1-.855.506l-2.872.838a.5.5 0 0 1-.62-.62l.838-2.872a2 2 0 0 1 .506-.854z"></path><path d="m15 5 3 3"></path></svg>Saját szavak</div><h2 class="mb-4 text-2xl font-bold tracking-tight">Add hozzá a saját szavaidat</h2><p class="mb-5 text-sm text-muted-foreground">Ha olyan szóval találkozol, ami nincs a top 10 000-ben, saját szóként felveheted — ugyanúgy viselkedik, mint a lista többi tagja.</p><ul class="flex flex-col gap-2.5 text-sm"><li class="flex items-start gap-2.5"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-check-check mt-0.5 size-4 shrink-0 text-primary"><path d="M18 6 7 17l-5-5"></path><path d="m22 10-7.5 7.5L13 16"></path></svg><span class="text-muted-foreground">Magyar jelentés, szófaj, szinonimák és példamondat tárolható</span></li><li class="flex items-start gap-2.5"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-check-check mt-0.5 size-4 shrink-0 text-primary"><path d="M18 6 7 17l-5-5"></path><path d="m22 10-7.5 7.5L13 16"></path></svg><span class="text-muted-foreground">Igealakok, főnév többes szám, melléknév fokozás</span></li><li class="flex items-start gap-2.5"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-check-check mt-0.5 size-4 shrink-0 text-primary"><path d="M18 6 7 17l-5-5"></path><path d="m22 10-7.5 7.5L13 16"></path></svg><span class="text-muted-foreground">Státuszok: Tudom, Tanulom, Később, Kiejtés</span></li><li class="flex items-start gap-2.5"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-check-check mt-0.5 size-4 shrink-0 text-primary"><path d="M18 6 7 17l-5-5"></path><path d="m22 10-7.5 7.5L13 16"></path></svg><span class="text-muted-foreground">Megjelenik a szólistában és az elemzésben is</span></li><li class="flex items-start gap-2.5"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-check-check mt-0.5 size-4 shrink-0 text-primary"><path d="M18 6 7 17l-5-5"></path><path d="m22 10-7.5 7.5L13 16"></path></svg><span class="text-muted-foreground">Flashcard paklikba importálható</span></li><li class="flex items-start gap-2.5"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-check-check mt-0.5 size-4 shrink-0 text-primary"><path d="M18 6 7 17l-5-5"></path><path d="m22 10-7.5 7.5L13 16"></path></svg><span class="text-muted-foreground">Extension-ből egyenesen hozzáadható Google AI segítségével</span></li></ul></div><div><div class="mb-3 inline-flex items-center gap-1.5 rounded-full border bg-muted px-3 py-1 text-xs font-medium text-muted-foreground"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-medal size-3"><path d="M7.21 15 2.66 7.14a2 2 0 0 1 .13-2.2L4.4 2.8A2 2 0 0 1 6 2h12a2 2 0 0 1 1.6.8l1.6 2.14a2 2 0 0 1 .14 2.2L16.79 15"></path><path d="M11 12 5.12 2.2"></path><path d="m13 12 5.88-9.8"></path><path d="M8 7h8"></path><circle cx="12" cy="17" r="5"></circle><path d="M12 18v-2h-.5"></path></svg>Teljesítmények</div><h2 class="mb-4 text-2xl font-bold tracking-tight">29 teljesítmény vár rád</h2><p class="mb-5 text-sm text-muted-foreground">Minden fontos mérföldkőhöz jár egy achievement — sorozat, szókincs, flashcard, kvíz és szövegelemzés kategóriákban.</p><div class="grid grid-cols-2 gap-2"><div class="flex items-center gap-2.5 rounded-lg border bg-card p-2.5"><span class="text-xl">🔥</span><div class="min-w-0"><p class="truncate text-xs font-semibold">7 napos sorozat</p><p class="truncate text-[10px] text-muted-foreground">7 egymást követő nap</p></div></div><div class="flex items-center gap-2.5 rounded-lg border bg-card p-2.5"><span class="text-xl">✅</span><div class="min-w-0"><p class="truncate text-xs font-semibold">100 szót tudom</p><p class="truncate text-[10px] text-muted-foreground">100 ismert szó</p></div></div><div class="flex items-center gap-2.5 rounded-lg border bg-card p-2.5"><span class="text-xl">🃏</span><div class="min-w-0"><p class="truncate text-xs font-semibold">100 flashcard</p><p class="truncate text-[10px] text-muted-foreground">100 kártya tanulva</p></div></div><div class="flex items-center gap-2.5 rounded-lg border bg-card p-2.5"><span class="text-xl">⭐</span><div class="min-w-0"><p class="truncate text-xs font-semibold">Tökéletes kvíz</p><p class="truncate text-[10px] text-muted-foreground">Minden válasz helyes</p></div></div><div class="flex items-center gap-2.5 rounded-lg border bg-card p-2.5"><span class="text-xl">📄</span><div class="min-w-0"><p class="truncate text-xs font-semibold">Folyékony olvasó</p><p class="truncate text-[10px] text-muted-foreground">90%+ érthetőség</p></div></div><div class="flex items-center gap-2.5 rounded-lg border bg-card p-2.5"><span class="text-xl">✏️</span><div class="min-w-0"><p class="truncate text-xs font-semibold">10 saját szó</p><p class="truncate text-[10px] text-muted-foreground">10 egyéni szó</p></div></div></div></div></div></div></section><section class="border-t bg-muted/40"><div class="mx-auto max-w-5xl px-6 py-20"><div class="mb-3 flex justify-center"><div class="inline-flex items-center gap-1.5 rounded-full border bg-muted px-3 py-1 text-xs font-medium text-muted-foreground"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-monitor-smartphone size-3"><path d="M18 8V6a2 2 0 0 0-2-2H4a2 2 0 0 0-2 2v7a2 2 0 0 0 2 2h8"></path><path d="M10 19v-3.96 3.15"></path><path d="M7 19h5"></path><rect width="6" height="10" x="16" y="12" rx="2"></rect></svg>Telepítés</div></div><h2 class="mb-3 text-center text-2xl font-bold tracking-tight">Használd alkalmazásként</h2><p class="mx-auto mb-12 max-w-xl text-center text-muted-foreground">Nincs App Store, nincs Play Store — telepítsd közvetlenül a böngészőből, és úgy néz ki mint egy natív alkalmazás.</p><div class="grid gap-6 md:grid-cols-3"><div class="rounded-xl border bg-card p-6"><div class="mb-4 flex h-10 w-10 items-center justify-center rounded-lg bg-blue-100 dark:bg-blue-950/40"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-monitor-smartphone size-5 text-blue-600 dark:text-blue-400"><path d="M18 8V6a2 2 0 0 0-2-2H4a2 2 0 0 0-2 2v7a2 2 0 0 0 2 2h8"></path><path d="M10 19v-3.96 3.15"></path><path d="M7 19h5"></path><rect width="6" height="10" x="16" y="12" rx="2"></rect></svg></div><h3 class="mb-1 font-semibold">Chrome / Edge (asztali)</h3><p class="mb-4 text-xs text-muted-foreground">A böngésző azonnal felajánlja a telepítést.</p><ol class="flex flex-col gap-1.5 text-xs text-muted-foreground"><li class="flex gap-2"><span class="font-bold text-foreground">1.</span> Nyisd meg az oldalt Chrome-ban vagy Edge-ben</li><li class="flex gap-2"><span class="font-bold text-foreground">2.</span> Kattints a <strong class="text-foreground">Telepítés</strong> ikonra a böngésző címsorában (⊕)</li><li class="flex gap-2"><span class="font-bold text-foreground">3.</span> Erősítsd meg — az alkalmazás megjelenik az asztalon</li></ol></div><div class="rounded-xl border bg-card p-6"><div class="mb-4 flex h-10 w-10 items-center justify-center rounded-lg bg-green-100 dark:bg-green-950/40"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-smartphone size-5 text-green-600 dark:text-green-400"><rect width="14" height="20" x="5" y="2" rx="2" ry="2"></rect><path d="M12 18h.01"></path></svg></div><h3 class="mb-1 font-semibold">Android (Chrome)</h3><p class="mb-4 text-xs text-muted-foreground">Chrome automatikusan felajánlja a telepítést.</p><ol class="flex flex-col gap-1.5 text-xs text-muted-foreground"><li class="flex gap-2"><span class="font-bold text-foreground">1.</span> Nyisd meg az oldalt Chrome-ban</li><li class="flex gap-2"><span class="font-bold text-foreground">2.</span> Koppints a <strong class="text-foreground">Hozzáadás a kezdőképernyőhöz</strong> értesítésre</li><li class="flex gap-2"><span class="font-bold text-foreground">3.</span> Vagy: ⋮ menü → <strong class="text-foreground">Alkalmazás telepítése</strong></li></ol></div><div class="rounded-xl border bg-card p-6 "><div class="mb-4 flex h-10 w-10 items-center justify-center rounded-lg bg-gray-100 dark:bg-gray-800"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-smartphone size-5 text-gray-600 dark:text-gray-400"><rect width="14" height="20" x="5" y="2" rx="2" ry="2"></rect><path d="M12 18h.01"></path></svg></div><h3 class="mb-1 font-semibold">iPhone / iPad (Safari)</h3><p class="mb-4 text-xs text-muted-foreground">iOS-on Safari-t kell használni a telepítéshez.</p><ol class="flex flex-col gap-1.5 text-xs text-muted-foreground"><li class="flex gap-2"><span class="font-bold text-foreground">1.</span> Nyisd meg az oldalt <strong class="text-foreground">Safari</strong>-ban</li><li class="flex gap-2"><span class="font-bold text-foreground">2.</span> Koppints a <strong class="text-foreground">Megosztás</strong> ikonra (⎙)</li><li class="flex gap-2"><span class="font-bold text-foreground">3.</span> Válaszd: <strong class="text-foreground">Hozzáadás a kezdőképernyőhöz</strong></li></ol></div></div></div></section><section class="border-t"><div class="mx-auto max-w-5xl px-6 py-20"><div class="grid items-center gap-12 md:grid-cols-2"><div><h2 class="mb-4 text-2xl font-bold tracking-tight">Miért érdemes a leggyakoribb szavakkal kezdeni?</h2><p class="mb-6 text-muted-foreground">A mindennapi angol szövegek és beszélgetések közel 90%-a csak a legtöbbször használt 3 000 szóból épül fel. Ha ezeket ismered, a legtöbb helyzetben boldogulni fogsz.</p><ul class="flex flex-col gap-3 text-sm"><li class="flex items-start gap-3"><div class="mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-primary/10"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-zap size-3 text-primary"><path d="M4 14a1 1 0 0 1-.78-1.63l9.9-10.2a.5.5 0 0 1 .86.46l-1.92 6.02A1 1 0 0 0 13 10h7a1 1 0 0 1 .78 1.63l-9.9 10.2a.5.5 0 0 1-.86-.46l1.92-6.02A1 1 0 0 0 11 14z"></path></svg></div><span class="text-muted-foreground">Gyors eredmények — a legfontosabb szavak előre kerülnek</span></li><li class="flex items-start gap-3"><div class="mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-primary/10"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-trending-up size-3 text-primary"><polyline points="22 7 13.5 15.5 8.5 10.5 2 17"></polyline><polyline points="16 7 22 7 22 13"></polyline></svg></div><span class="text-muted-foreground">Mérhető haladás — látod, mennyi szót ismersz már</span></li><li class="flex items-start gap-3"><div class="mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-primary/10"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-star size-3 text-primary"><path d="M11.525 2.295a.53.53 0 0 1 .95 0l2.31 4.679a2.123 2.123 0 0 0 1.595 1.16l5.166.756a.53.53 0 0 1 .294.904l-3.736 3.638a2.123 2.123 0 0 0-.611 1.878l.882 5.14a.53.53 0 0 1-.771.56l-4.618-2.428a2.122 2.122 0 0 0-1.973 0L6.396 21.01a.53.53 0 0 1-.77-.56l.881-5.139a2.122 2.122 0 0 0-.611-1.879L2.16 9.795a.53.53 0 0 1 .294-.906l5.165-.755a2.122 2.122 0 0 0 1.597-1.16z"></path></svg></div><span class="text-muted-foreground">Nehézségi szintek — kezdőtől haladóig</span></li></ul></div><div class="flex flex-col gap-3"><div class="rounded-xl border bg-card p-4"><div class="mb-2 flex items-center justify-between text-sm"><span class="font-medium">Kezdő</span><span class="text-muted-foreground">1–2 000</span></div><div class="mb-2 h-1.5 w-full overflow-hidden rounded-full bg-secondary"><div class="h-1.5 rounded-full bg-primary/40" style="width:20%"></div></div><p class="text-xs text-muted-foreground">Alapvető szavak, amelyek nélkül nem boldogulsz</p></div><div class="rounded-xl border bg-card p-4"><div class="mb-2 flex items-center justify-between text-sm"><span class="font-medium">Középhaladó</span><span class="text-muted-foreground">2 001–6 000</span></div><div class="mb-2 h-1.5 w-full overflow-hidden rounded-full bg-secondary"><div class="h-1.5 rounded-full bg-primary/70" style="width:50%"></div></div><p class="text-xs text-muted-foreground">A hétköznapi kommunikáció szókincse</p></div><div class="rounded-xl border bg-card p-4"><div class="mb-2 flex items-center justify-between text-sm"><span class="font-medium">Haladó</span><span class="text-muted-foreground">6 001–10 000</span></div><div class="mb-2 h-1.5 w-full overflow-hidden rounded-full bg-secondary"><div class="h-1.5 rounded-full bg-primary" style="width:100%"></div></div><p class="text-xs text-muted-foreground">Ritkább, de hasznos szavak</p></div></div></div></div></section><section class="border-t bg-muted/40"><div class="mx-auto max-w-5xl px-6 py-20"><div class="mb-10 text-center"><div class="mb-3 inline-flex items-center gap-1.5 rounded-full border bg-muted px-3 py-1 text-xs font-medium text-muted-foreground"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-flask-conical size-3"><path d="M14 2v6a2 2 0 0 0 .245.96l5.51 10.08A2 2 0 0 1 18 22H6a2 2 0 0 1-1.755-2.96l5.51-10.08A2 2 0 0 0 10 8V2"></path><path d="M6.453 15h11.094"></path><path d="M8.5 2h7"></path></svg>Tudományosan megalapozott</div><h2 class="mb-3 text-2xl font-bold tracking-tight">Honnan származik a szólista?</h2><p class="mx-auto max-w-2xl text-muted-foreground">A 10 000 leggyakoribb angol szó nem véletlenszerűen összeválogatott lista — korpusznyelvészeti kutatások eredménye, amelyet évtizedek óta használnak nyelvoktatásban és kutatásban.</p></div><div class="grid gap-6 md:grid-cols-2"><div class="rounded-xl border bg-card p-6"><h3 class="mb-2 font-semibold">BNC &amp; COCA korpuszok</h3><p class="text-sm text-muted-foreground">A lista a <strong class="text-foreground">British National Corpus (BNC)</strong> és a<!-- --> <strong class="text-foreground">Corpus of Contemporary American English (COCA)</strong> adatain alapul — több száz millió szót tartalmazó, gondosan összeállított szöveggyűjteményeken.</p></div><div class="rounded-xl border bg-card p-6"><h3 class="mb-2 font-semibold">Paul Nation kutatása</h3><p class="text-sm text-muted-foreground">A frekvencialisták összeállításában meghatározó szerepet játszott<!-- --> <strong class="text-foreground">Paul Nation</strong>, a Victoria University of Wellington professzora, akinek munkája a szókincs-fejlesztés tudományos alapjává vált.</p></div><div class="rounded-xl border bg-card p-6"><h3 class="mb-2 font-semibold">1 000-es egységek</h3><p class="text-sm text-muted-foreground">A szavak 10 darab, egyenként 1 000 szavas csoportba vannak rendezve, frekvencia szerint. Az első 2 000 szó a mindennapi kommunikáció alapját adja, a 10 000. szóig eljutva professzionális és akadémiai szövegek is érthetővé válnak.</p></div><div class="rounded-xl border bg-card p-6"><h3 class="mb-2 font-semibold">Szófaji kategóriák</h3><p class="text-sm text-muted-foreground">A lista főneveket, igéket, mellékneveket és határozószókat is tartalmaz —<!-- --> <strong class="text-foreground">headword</strong> formában tárolva, ami azt jelenti, hogy pl. a <em>run</em> egyetlen bejegyzés, nem pedig külön a <em>runs</em>, <em>ran</em>,<!-- --> <em>running</em>.</p></div></div></div></section><section class="border-t"><div class="mx-auto max-w-5xl px-6 py-16"><div class="rounded-2xl border bg-muted/40 px-8 py-10"><div class="flex flex-col gap-6 md:flex-row md:items-center md:justify-between"><div class="flex items-start gap-4"><div class="flex h-10 w-10 shrink-0 items-center justify-center rounded-lg bg-primary/10"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-lightbulb size-5 text-primary"><path d="M15 14c.2-1 .7-1.7 1.5-2.5 1-.9 1.5-2.2 1.5-3.5A6 6 0 0 0 6 8c0 1 .2 2.2 1.5 3.5.7.7 1.3 1.5 1.5 2.5"></path><path d="M9 18h6"></path><path d="M10 22h4"></path></svg></div><div><h3 class="mb-1 font-semibold">Fejlesztési ötleted van, vagy hibát találtál?</h3><p class="text-sm text-muted-foreground">Szívesen fogadom a visszajelzéseket — legyen az új funkció ötlete, apró hiba vagy bármi más.</p></div></div><div class="flex shrink-0 flex-col gap-2 sm:flex-row"><a href="https://codebarley.hu" target="_blank" rel="noopener noreferrer" class="inline-flex items-center justify-center gap-2 rounded-lg border bg-background px-4 py-2.5 text-sm font-medium transition-colors hover:bg-muted"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-external-link size-4"><path d="M15 3h6v6"></path><path d="M10 14 21 3"></path><path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"></path></svg>codebarley.hu</a><a href="mailto:info@codebarley.hu" class="inline-flex items-center justify-center gap-2 rounded-lg bg-primary px-4 py-2.5 text-sm font-medium text-primary-foreground transition-opacity hover:opacity-90"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-mail size-4"><rect width="20" height="16" x="2" y="4" rx="2"></rect><path d="m22 7-8.97 5.7a1.94 1.94 0 0 1-2.06 0L2 7"></path></svg>info@codebarley.hu</a></div></div></div></div></section><section class="border-t"><div class="mx-auto max-w-5xl px-6 py-16"><div class="relative overflow-hidden rounded-2xl bg-zinc-900 px-8 py-12 text-white dark:bg-zinc-800"><div class="absolute -right-16 -top-16 size-64 rounded-full bg-white/5"></div><div class="absolute -bottom-20 -left-10 size-48 rounded-full bg-white/5"></div><div class="relative flex flex-col items-start gap-6 md:flex-row md:items-center md:justify-between"><div class="flex items-center gap-4"><div class="flex h-12 w-12 shrink-0 items-center justify-center rounded-xl bg-white/10"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-code-xml size-6 text-white"><path d="m18 16 4-4-4-4"></path><path d="m6 8-4 4 4 4"></path><path d="m14.5 4-5 16"></path></svg></div><div><div class="text-xs font-medium uppercase tracking-widest text-white/50">Fejlesztő</div><div class="text-xl font-bold tracking-tight">codebarley.hu</div><div class="mt-0.5 text-sm text-white/60">Webes megoldások, modern technológiákkal</div></div></div><a href="https://codebarley.hu" target="_blank" rel="noopener noreferrer" class="group flex items-center gap-2 rounded-xl bg-white px-5 py-2.5 text-sm font-semibold text-zinc-900 transition-opacity hover:opacity-90">Megnézem<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-external-link size-4 transition-transform group-hover:translate-x-0.5"><path d="M15 3h6v6"></path><path d="M10 14 21 3"></path><path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"></path></svg></a></div></div></div></section><footer class="border-t"><div class="mx-auto flex max-w-5xl flex-wrap items-center justify-between gap-4 px-6 py-6 text-sm text-muted-foreground"><div class="flex items-center gap-2"><div class="flex h-6 w-6 items-center justify-center rounded bg-primary"><svg viewBox="60 90 392 330" class="size-3.5 text-primary-foreground" fill="none" xmlns="http://www.w3.org/2000/svg"><text x="256" y="356" font-family="&#x27;Helvetica Neue&#x27;, Helvetica, Arial, sans-serif" font-size="300" font-weight="700" fill="white" text-anchor="middle" letter-spacing="-10">W</text><rect x="80" y="390" width="352" height="22" rx="11" fill="white" opacity="0.9"></rect></svg></div><span>TopWords</span></div><div class="flex flex-wrap items-center gap-4"><a class="transition-colors hover:text-foreground" href="/terms">ÁSZF</a><span>·</span><a class="transition-colors hover:text-foreground" href="/privacy">Adatkezelés</a><span>·</span><a href="https://codebarley.hu" target="_blank" rel="noopener noreferrer" class="transition-colors hover:text-foreground">Készítette: codebarley.hu</a></div></div></footer></div></div>